<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Portal do aluno - Stagium</title>@fonts
<style>:root{--bg:#f4f7fb;--surface:#fff;--text:#122033;--muted:#637083;--border:#d8e2ee;--accent:#155ea8;--green:#16794f;--red:#b42318;font-family:"Instrument Sans",system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text)}.page{width:min(100%,920px);margin:auto;padding:28px 18px}.header{display:flex;align-items:center;justify-content:space-between;gap:16px;border-bottom:1px solid var(--border);padding-bottom:20px}.brand{margin:0;color:var(--accent);font-size:14px;font-weight:800}h1{margin:3px 0 0;font-size:30px}.logout{border:0;background:transparent;color:var(--red);font:inherit;font-weight:700;cursor:pointer}.grid{display:grid;grid-template-columns:1.15fr .85fr;gap:20px;margin-top:24px}.card{border:1px solid var(--border);border-radius:12px;background:var(--surface);padding:22px;box-shadow:0 8px 22px rgba(18,32,51,.06)}h2{margin:0 0 8px;font-size:19px}.muted{color:var(--muted);font-size:14px}.company{margin:18px 0;border-radius:8px;background:#eef4fb;padding:14px}.status{min-height:48px;margin:16px 0;border:1px solid var(--border);border-radius:8px;padding:13px;font-size:14px}.mark{width:100%;border:0;border-radius:8px;background:var(--accent);color:#fff;padding:14px;font:inherit;font-size:16px;font-weight:800;cursor:pointer}.mark:disabled{background:#8fa4ba}.log{display:flex;justify-content:space-between;gap:10px;padding:12px 0;border-bottom:1px solid var(--border)}.badge{border-radius:999px;padding:4px 9px;font-size:12px;font-weight:800}.in{background:#e7f5ee;color:var(--green)}.out{background:#fff0ef;color:var(--red)}@media(max-width:700px){.grid{grid-template-columns:1fr}.header{align-items:flex-start}h1{font-size:25px}}</style></head><body><main class="page"><header class="header"><div><p class="brand">STAGIUM · ÁREA EXCLUSIVA</p><h1>Olá, {{ $student->name }}</h1></div><form action="{{ route('logout') }}" method="POST">@csrf<button class="logout">Sair</button></form></header>
<section class="grid"><div class="card"><h2>Registro de estágio</h2><p class="muted">Use a localização do aparelho para registrar entrada e saída na empresa.</p>@if($company)<div class="company"><strong>{{ $company->corporate_name }}</strong><br><span class="muted">{{ $company->address }} · raio permitido: {{ $company->attendance_radius_meters }} m</span></div>@else<div class="company">Nenhuma empresa de estágio foi vinculada ao seu termo.</div>@endif<div id="status" class="status">Permita o acesso à localização para registrar o ponto.</div><button id="mark" class="mark" type="button" @disabled(!$company || $company->latitude===null)>{{ $lastLog?->type === 'in' ? 'Registrar saída' : 'Registrar entrada' }}</button></div>
<div class="card"><h2>Últimos registros</h2><p class="muted">Curso: {{ $student->course?->name ?? 'Não informado' }}</p>@forelse($logs as $log)<div class="log"><div><strong>{{ $log->logged_at->format('d/m/Y H:i') }}</strong><br><span class="muted">{{ $log->company->corporate_name }} · {{ $log->distance_meters }} m</span></div><span class="badge {{ $log->type }}">{{ $log->type==='in'?'Entrada':'Saída' }}</span></div>@empty<p class="muted">Você ainda não registrou nenhum ponto.</p>@endforelse</div></section></main>
<script>const button=document.getElementById('mark');const status=document.getElementById('status');button?.addEventListener('click',()=>{if(!navigator.geolocation){status.textContent='Este navegador não oferece geolocalização.';return}button.disabled=true;status.textContent='Obtendo sua localização...';navigator.geolocation.getCurrentPosition(async position=>{try{status.textContent='Validando sua posição na empresa...';const response=await fetch('{{ route('student.time-log.mark') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({latitude:position.coords.latitude,longitude:position.coords.longitude})});const data=await response.json();if(!response.ok)throw new Error(data.message||'Não foi possível registrar.');status.textContent=data.message;setTimeout(()=>location.reload(),900)}catch(error){status.textContent=error.message;button.disabled=false}},error=>{status.textContent='Não foi possível obter a localização: '+error.message;button.disabled=false},{enableHighAccuracy:true,timeout:15000,maximumAge:0})});</script></body></html>
